<script>
 import {onMount,onDestroy} from 'svelte';
 import {page} from '$app/stores';
 import {listDeployments} from '$lib/api.js';
 import {notify} from '$lib/stores.js';
 import Button from '$lib/components/Button.svelte';
 let deployments=[],loading=true,refreshing=false,filter='all',search='',refreshTimer;
 async function load(silent=false){if(refreshing)return;refreshing=true;const r=await listDeployments($page.url.searchParams.get('project_id')||'');if(r.ok)deployments=r.data.deployments||[];else if(!silent)notify(r.error||'Не удалось загрузить историю деплоев','error');loading=false;refreshing=false;}
 onMount(()=>{load();refreshTimer=setInterval(()=>load(true),15000);});
 onDestroy(()=>{if(refreshTimer)clearInterval(refreshTimer);});
 $: successful=deployments.filter(d=>d.details?.ok===true).length;
 $: failed=deployments.filter(d=>d.details?.ok===false).length;
 $: rollbacks=deployments.filter(d=>d.action==='site_rollback').length;
 $: filtered=deployments.filter(d=>{const ok=d.details?.ok===true;if(filter==='success'&&!ok)return false;if(filter==='failed'&&ok)return false;const q=search.trim().toLowerCase();return !q||[d.details?.site_id,d.device,d.action,d.details?.commit_hash,d.details?.error].some(v=>String(v||'').toLowerCase().includes(q));});
 function label(action){return ({site_deploy:'Deploy',site_rebuild:'Rebuild',site_rollback:'Rollback',site_restart:'Restart'})[action]||action;}
 function relative(value){const t=new Date(value).getTime();if(!Number.isFinite(t))return '—';const s=Math.max(0,Math.floor((Date.now()-t)/1000));if(s<60)return 'только что';if(s<3600)return Math.floor(s/60)+' мин. назад';if(s<86400)return Math.floor(s/3600)+' ч. назад';return Math.floor(s/86400)+' дн. назад';}
 function shortCommit(value){return value?String(value).slice(0,12):'';}
</script>
<div class="page-header"><div><div class="eyebrow">DELIVERY / OVERVIEW</div><h1 class="page-title">Deployment Dashboard</h1><p class="page-desc">История релизов, результаты деплоя и состояние последних операций.</p></div><Button on:click={()=>load()} disabled={refreshing}>↻ Обновить</Button></div>
<div class="stats">
 <article><span>Всего операций</span><strong>{deployments.length}</strong><small>Последние 100</small></article>
 <article><span>Успешно</span><strong class="good">{successful}</strong><small>Завершены без ошибок</small></article>
 <article><span>Ошибки</span><strong class="bad">{failed}</strong><small>Требуют внимания</small></article>
 <article><span>Откаты</span><strong>{rollbacks}</strong><small>Возврат к прошлому релизу</small></article>
</div>
<div class="toolbar"><div class="filters"><button class:active={filter==='all'} on:click={()=>filter='all'}>Все</button><button class:active={filter==='success'} on:click={()=>filter='success'}>Успешные</button><button class:active={filter==='failed'} on:click={()=>filter='failed'}>С ошибками</button></div><input class="input search" bind:value={search} placeholder="Поиск по сайту, устройству или commit…"/></div>
{#if loading}<div class="empty">Загружаем историю деплоев…</div>{:else if !filtered.length}<div class="empty">{deployments.length?'По заданным условиям ничего не найдено.':'Деплоев пока нет. Запусти Deploy или Rebuild на странице сайта.'}</div>{:else}
<section class="history">{#each filtered as d (d.id)}<article class="entry"><span class:failed={d.details?.ok===false} class="entry-icon">{d.details?.ok===false?'!':d.action==='site_rollback'?'↶':'↑'}</span><div class="entry-main"><div class="entry-title"><strong>{label(d.action)}</strong><span class:failed-text={d.details?.ok===false} class="result">{d.details?.ok===false?'Failed':'Succeeded'}</span></div><div class="entry-meta"><b>{d.details?.site_id||'Неизвестный сайт'}</b><span>{d.device||'Устройство'}</span></div>{#if d.details?.commit_hash}<code>{shortCommit(d.details.commit_hash)}</code>{/if}{#if d.details?.error}<p class="error-text">{d.details.error}</p>{/if}</div><time title={new Date(d.created_at).toLocaleString()}>{relative(d.created_at)}<small>{new Date(d.created_at).toLocaleString()}</small></time></article>{/each}</section>
{/if}
<p class="footnote">Автообновление каждые 15 секунд. Полная история релизов и ручной откат доступны во вкладке Releases конкретного сайта.</p>
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#a1a1aa;font-weight:700;margin-bottom:7px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:18px}.stats article{display:grid;gap:7px;padding:15px;border:1px solid #27272a;border-radius:8px;background:#18181b}.stats span,.stats small{font-size:10px;color:#a1a1aa}.stats strong{font-size:25px;font-weight:650;letter-spacing:-.04em}.stats strong.good{color:#22c55e}.stats strong.bad{color:#ef4444}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:0 0 12px}.filters{display:flex;gap:4px;padding:3px;border:1px solid #27272a;border-radius:7px;background:#111113}.filters button{border:0;background:transparent;color:#a1a1aa;padding:6px 10px;border-radius:5px;font-size:10px}.filters button.active{background:#27272a;color:#fafafa}.search{max-width:330px}.history{border:1px solid #27272a;border-radius:8px;background:#18181b;overflow:hidden}.entry{display:flex;align-items:flex-start;gap:12px;padding:14px;border-bottom:1px solid #27272a}.entry:last-child{border:0}.entry-icon{width:30px;height:30px;display:grid;place-items:center;flex:none;border-radius:7px;background:#14291d;color:#22c55e;font-weight:700}.entry-icon.failed{background:#321b1b;color:#ef4444}.entry-main{flex:1;min-width:0;display:grid;gap:5px}.entry-title{display:flex;align-items:center;gap:8px}.entry-title strong{font-size:12px;font-weight:600}.result{font-size:9px;color:#22c55e}.result.failed-text{color:#ef4444}.entry-meta{display:flex;flex-wrap:wrap;gap:9px;color:#a1a1aa;font-size:10px}.entry-meta b{color:#e4e4e7;font-weight:550}.entry code{font:10px var(--mono,monospace);color:#a1a1aa}.error-text{font-size:10px;color:#fca5a5;overflow-wrap:anywhere}.entry time{display:grid;gap:3px;text-align:right;white-space:nowrap;font-size:10px;color:#d4d4d8}.entry time small{font-size:9px;color:#71717a}.footnote{margin-top:12px;color:#71717a;font-size:10px}@media(max-width:760px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.toolbar{align-items:stretch;flex-direction:column}.search{max-width:none}.entry time{white-space:normal;max-width:100px}}
</style>